run_generated_snippet: doors = revit_ro.get_elements("Doors")
cols = revit_ro.get_elements("Columns")
threshold2 = 3.0 * 3.0
close = []
for d in doors:
    db = revit_ro.get_geometry_bbox(d["id"])
    if db == None:
        continue
    dc = db.get("center")
    if dc == None:
        continue
    for c in cols:
        cb = revit_ro.get_geometry_bbox(c["id"])
        if cb == None:
            continue
        cc = cb.get("center")
        if cc == None:
            continue
        dx = dc[0] - cc[0]
        dy = dc[1] - cc[1]
        dz = dc[2] - cc[2]
        if dx*dx + dy*dy + dz*dz <= threshold2:
            close.append(d["id"]) 
            break
result = {"count": len(close), "door_ids": close}

run_generated_snippet: rooms = revit_ro.get_elements("Rooms")
cols = revit_ro.get_elements("Columns")
output = []
for r in rooms:
    rb = revit_ro.get_geometry_bbox(r["id"])
    if rb == None:
        continue
    rmin = rb["min"]
    rmax = rb["max"]
    contained = []
    for c in cols:
        cb = revit_ro.get_geometry_bbox(c["id"])
        if cb == None:
            continue
        center = cb.get("center")
        if center == None:
            cm = cb["min"]; cM = cb["max"]
            center = [(cm[0]+cM[0])/2.0, (cm[1]+cM[1])/2.0, (cm[2]+cM[2])/2.0]
        if center[0] >= rmin[0] and center[0] <= rmax[0] and center[1] >= rmin[1] and center[1] <= rmax[1] and center[2] >= rmin[2] and center[2] <= rmax[2]:
            contained.append(c["id"])
    if contained:
        output.append({"room_id": r["id"], "room_name": revit_ro.get_param(r["id"], "Name"), "column_ids": contained})
result = output

run_generated_snippet: cols = revit_ro.get_elements("Columns")
pts = []
for c in cols:
    ln = revit_ro.get_line(c["id"])
    if ln != None and "point" in ln:
        pts.append({"id": c["id"], "p": ln["point"]})
if len(pts) < 2:
    result = {"error": "Not enough columns with point geometry (need >=2).", "found": len(pts)}
else:
    maxd2 = -1.0
    pair = (None, None)
    for i in range(len(pts)):
        p1 = pts[i]["p"]
        for j in range(i+1, len(pts)):
            p2 = pts[j]["p"]
            dx = p1[0] - p2[0]
            dy = p1[1] - p2[1]
            dz = p1[2] - p2[2]
            d2 = dx*dx + dy*dy + dz*dz
            if d2 > maxd2:
                maxd2 = d2
                pair = (pts[i]["id"], pts[j]["id"])
    if maxd2 < 0:
        result = {"error": "Could not compute distances."}
    else:
        if maxd2 == 0:
            dist = 0.0
        else:
            # Newton-Raphson sqrt of maxd2
            g = maxd2
            for _ in range(20):
                g = 0.5*(g + maxd2 / g)
            dist = g
        result = {"column_id_1": pair[0], "column_id_2": pair[1], "distance_m": round(dist, 3)}
